from concurrent.futures import ThreadPoolExecutor

import pytest

DEFAULT_WORKERS = 4


def square(x: int) -> int:
    return x * x


def sum_squares_with(xs: list[int], workers: int) -> int:
    """Sum of x*x over xs, computing the squares with a thread pool of
    `workers` threads. The result is exact (Python ints) and identical for
    every worker count. Does not mutate xs. Returns 0 for an empty list.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        squares = list(pool.map(square, xs))
    return sum(squares)


def sum_squares(xs: list[int]) -> int:
    """Sum of the squares of every element of xs, computed in parallel using
    a thread pool with DEFAULT_WORKERS threads. Equivalent to
    sum_squares_with(xs, DEFAULT_WORKERS).
    """
    return sum_squares_with(xs, DEFAULT_WORKERS)


def test_sum_squares_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_single() -> None:
    assert sum_squares([7]) == 49


def test_sum_squares_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_sum_squares_big_ints_exact() -> None:
    big = 10**20
    assert sum_squares([big, -big]) == 2 * big * big


def test_sum_squares_does_not_mutate_input() -> None:
    xs = [3, -1, 2]
    sum_squares(xs)
    assert xs == [3, -1, 2]


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 16, 64])
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-50, 150))
    expected = sum(x * x for x in xs)
    assert sum_squares_with(xs, workers) == expected


@pytest.mark.parametrize("workers", [1, 2, 5, 32])
def test_workers_more_than_items(workers: int) -> None:
    assert sum_squares_with([2, 3], workers) == 13
    assert sum_squares_with([], workers) == 0


def test_default_matches_explicit_workers() -> None:
    xs = [5, -4, 3, 2, 1]
    assert sum_squares(xs) == sum_squares_with(xs, DEFAULT_WORKERS)
    assert sum_squares(xs) == sum_squares_with(xs, 1)


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_workers_raises(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares_with([1, 2, 3], workers)
